('0c5080eb-bd5c-48fb-83f4-8b4cfc2da84a', '9c3e63e3-3645-4e74-b9b9-b9971bbd8288', 'NMCN-RN', 60, 10, '2026-06-03 14:18:26.715059+00', 2, '{"0":"C","1":"B","2":"B","3":"C","4":"C","5":"C","6":"C","7":"A","8":"D","9":"C"}', '[{"id":"nmcn_017","topic":"Medical-Surgical Nursing","correct":"C","options":{"A":"Epigastric region","B":"Right upper quadrant","C":"Right lower quadrant","D":"Left lower quadrant"},"examType":"NMCN-RN","question":"In appendicitis, pain is typically localized to:"},{"id":"nmcn_015","topic":"Medical-Surgical Nursing","correct":"B","options":{"A":"Pale and dry","B":"Red and moist","C":"Blue and dusky","D":"Black and hard"},"examType":"NMCN-RN","question":"The stoma should appear:"},{"id":"nmcn_126","topic":"Medical-Surgical Nursing","correct":"C","options":{"A":"Red blood cells","B":"Bile","C":"Clotting factors","D":"Insulin"},"examType":"NMCN-RN","question":"A patient with liver cirrhosis is at high risk for bleeding because the liver fails to produce:"},{"id":"nmcn_069","topic":"Medical-Surgical Nursing","correct":"B","options":{"A":"Keep the affected leg internally rotated","B":"Maintain the affected leg in abduction","C":"Place pillows directly under the knee","D":"Encouraging early weight-bearing on the affected leg"},"examType":"NMCN-RN","question":"The appropriate nursing intervention for a client with a fractured hip is to:"},{"id":"nmcn_078","topic":"Medical-Surgical Nursing","correct":"C","options":{"A":"Red blood cells","B":"Insulin","C":"Clotting factors","D":"Electrolytes"},"examType":"NMCN-RN","question":"A patient with liver failure is at high risk for bleeding because the liver synthesizes:"},{"id":"nmcn_128","topic":"Medical-Surgical Nursing","correct":"C","options":{"A":"0.45% Sodium Chloride","B":"5% Dextrose in 0.9% Sodium Chloride","C":"0.9% Sodium Chloride","D":"3% Sodium Chloride"},"examType":"NMCN-RN","question":"Which solution is isotonic?"},{"id":"nmcn_018","topic":"Medical-Surgical Nursing","correct":"C","options":{"A":"Sucking the venom out","B":"Applying a tourniquet","C":"Keeping the affected limb immobilized and below heart level","D":"Applying ice to the bite site"},"examType":"NMCN-RN","question":"The first aid management of a snake bite includes:"},{"id":"nmcn_019","topic":"Medical-Surgical Nursing","correct":"B","options":{"A":"Sharp and stabbing lasting seconds","B":"Crushing substernal pressure radiating to the left arm","C":"Burning in the epigastric area only","D":"Pain that improves with exercise"},"examType":"NMCN-RN","question":"A client experiencing a myocardial infarction may describe chest pain as:"},{"id":"nmcn_014","topic":"Medical-Surgical Nursing","correct":"B","options":{"A":"Hypoglycemia, bradycardia, hypothermia","B":"Hyperglycemia, ketosis, metabolic acidosis","C":"Hypertension, proteinuria, edema","D":"Polyphagia, weight gain, lethargy"},"examType":"NMCN-RN","question":"The triad of symptoms in diabetic ketoacidosis includes:"},{"id":"nmcn_020","topic":"Medical-Surgical Nursing","correct":"C","options":{"A":"Allowing visitors to smoke in the hallway","B":"Using wool blankets on the client''s bed","C":"Ensuring no open flames are near the oxygen source","D":"Oiling the oxygen equipment to keep it functional"},"examType":"NMCN-RN","question":"The nurse is caring for a client on oxygen therapy via nasal cannula at 4 L/min. Which is an important safety measure?"}]'),
